class Solution {
public:
    string nextPalindrome(string num) {
        int half = num.size() / 2;
        string left = num.substr(0, half);
        if (!next_permutation(left.begin(), left.end())) return "";
        string right = left;
        reverse(right.begin(), right.end());
        return left + (num.size() % 2 ? num.substr(half, 1) : "") + right;
    }
};
